import { rumUserSessionsClient } from "@dynatrace-sdk/client-classic-environment-v1";

function normalizeHost(raw) {
  if (!raw) return "";

  let s = String(raw).trim().toLowerCase();

  // Remove protocol
  s = s.replace(/^https?:\/\//, "");

  // Remove path (everything after first '/')
  const slashIdx = s.indexOf("/");
  if (slashIdx >= 0) s = s.slice(0, slashIdx);

  // Remove query (defensive, if query snuck in without a '/')
  const qIdx = s.indexOf("?");
  if (qIdx >= 0) s = s.slice(0, qIdx);

  // Remove port
  const colonIdx = s.indexOf(":");
  if (colonIdx >= 0) s = s.slice(0, colonIdx);

  // Remove leading www.
  if (s.startsWith("www.")) s = s.slice(4);

  // Remove trailing dot
  s = s.replace(/\.+$/, "");

  return s;
}

async function runUsqlWindow({ query, startTimestamp, endTimestamp, offsetUtc, pageSize }) {
  let pageOffset = 0;
  const allValues = [];

  while (true) {
    const resp = await rumUserSessionsClient.getUsqlResultAsTable({
      query,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
      pageOffset,
    });

    const values = resp?.values ?? [];
    allValues.push(...values);

    // Stop if last page returned fewer than pageSize rows
    if (!pageSize || values.length < pageSize) break;

    pageOffset += pageSize;
  }

  return allValues;
}

export default async function () {
  const now = Date.now();

  // Tune these:
  const windowDays = 3;        // each query covers 3 days
  const windowCount = 10;      // number of windows to run (10*3 = 30 days total)
  const pageSize = 5000;       // optional paging

  // Base query WITHOUT timeframe
  // Keep the grouping/order/limit as needed.
  const usqlQuery =
    'select application, domain, count(*) ' +
    'from useraction ' +
    'where usersession.userType = "REAL_USER" ' +
    'group by application, domain ' +
    'order by application, domain ' +
    'LIMIT 5000';

  const offsetUtc = -240;

  // 1) Run multiple time windows and append rows
  const allRows = [];
  const windowMs = windowDays * 24 * 3600 * 1000;

  for (let i = 0; i < windowCount; i++) {
    const endTimestamp = now - i * windowMs;
    const startTimestamp = endTimestamp - windowMs;

    const values = await runUsqlWindow({
      query: usqlQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    // Map to row objects (and optionally tag which window they came from)
    for (const row of values) {
      const domainRaw = row[1];

      // Skip null/empty domainRaw early
      if (domainRaw == null) continue;

      const domain = normalizeHost(domainRaw);

      // Skip if normalization yields empty or "null-like"
      if (!domain || domain === "null" || domain === "(null)" || domain === "undefined") continue;

      allRows.push({
        application: row[0],
        domain_raw: domainRaw,
        domain,
        actions: Number(row[2]) || 0,
        // window_index: i,
      });
    }

  }

  // 2) Deduplicate/merge by (application + normalized domain)
  // Here we SUM actions across windows.
  const merged = new Map();
  for (const r of allRows) {
    if (!r.domain) continue;

    const key = `${r.application}||${r.domain}`;
    const existing = merged.get(key);
    if (existing) {
      existing.actions += r.actions;
    } else {
      merged.set(key, {
        application: r.application,
        domain: r.domain,
        actions: r.actions,
      });
    }
  }

  const records = Array.from(merged.values());

  // 3) Return as dashboard table
  return {
    records,
    types: [
      {
        indexRange: [0, records.length],
        mappings: {
          application: { type: "string" },
          domain: { type: "string" },
          actions: { type: "float" },
        },
      },
    ],
  };
}

