export default async function () {
  const now = Date.now();

  // Tune these:
  const windowDays = 3;     // each query covers 3 days
  const windowCount = 10;   // number of windows to run (10*3 = 30 days total)
  const pageSize = 5000;    // optional paging; adjust if needed
  const offsetUtc = -240;   // can change

  // New query includes distinct count of URLs per (browser monitor, domain)
  const usqlQuery =
    'SELECT usersession.browserMonitorName, useraction.domain, ' +
    'COUNT(DISTINCT useraction.targetUrl) AS distinct_urls ' +
    'FROM usersession ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY usersession.browserMonitorName, useraction.domain ' +
    'ORDER BY usersession.browserMonitorName, useraction.domain ' +
    'LIMIT 5000';

  // Aggregate per key across multiple windows:
  // - default: take MAX distinct_urls across windows (avoids double-counting across overlapping windows)
  // - exception: if SUM across windows > 50, take SUM
  const agg = new Map(); // key -> { browserMonitorName, domain, maxDistinctUrls, sumDistinctUrls }

  const windowMs = windowDays * 24 * 3600 * 1000;

  for (let i = 0; i < windowCount; i++) {
    const endTimestamp = now - i * windowMs;
    const startTimestamp = endTimestamp - windowMs;

    const values = await runUsqlWindow({
      query: usqlQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of values) {
      const browserMonitorName = row[0];
      const domainRaw = row[1];
      const distinctUrlsRaw = row[2];

      const domain = normalizeHost(domainRaw);
      const distinct_urls = Number(distinctUrlsRaw) || 0;

      if (!browserMonitorName || !domain) continue;

      const key = `${browserMonitorName}||${domain}`;
      const existing = agg.get(key);

      if (!existing) {
        agg.set(key, {
          browserMonitorName,
          domain,
          maxDistinctUrls: distinct_urls,
          sumDistinctUrls: distinct_urls,
        });
      } else {
        existing.sumDistinctUrls += distinct_urls;
        if (distinct_urls > existing.maxDistinctUrls) {
          existing.maxDistinctUrls = distinct_urls;
        }
      }
    }
  }

  // Apply rule: MAX unless SUM > 50 then SUM
  const records = Array.from(agg.values()).map((r) => {
    const finalDistinctUrls = r.sumDistinctUrls > 50 ? r.sumDistinctUrls : r.maxDistinctUrls;

    return {
      browser_monitors: r.browserMonitorName,
      domain: r.domain,
      distinct_urls: finalDistinctUrls,
    };
  });

  // Optional: stable sort
  records.sort((a, b) => {
    if (a.browserMonitorName !== b.browserMonitorName) {
      return a.browserMonitorName.localeCompare(b.browserMonitorName);
    }
    return a.domain.localeCompare(b.domain);
  });

  // Return as dashboard table
  return {
    records,
    types: [
      {
        indexRange: [0, records.length],
        mappings: {
          browser_monitors: { type: "string" },
          domain: { type: "string" },
          distinct_urls: { type: "number" }
        },
      },
    ],
  };
}

