import { rumUserSessionsClient } from "@dynatrace-sdk/client-classic-environment-v1";

/**
 * Normalize domain/host similarly to your app.js:
 * - trim, lowercase
 * - remove protocol, path, query, port
 * - remove leading www.
 * - treat null-like strings as empty
 * - remove trailing dots
 */
function normalizeHost(raw) {
  if (raw == null) return "";

  let s = String(raw).trim().toLowerCase();
  if (!s || s === "null" || s === "(null)" || s === "undefined") return "";

  s = s.replace(/^https?:\/\//, "");

  const slashIdx = s.indexOf("/");
  if (slashIdx >= 0) s = s.slice(0, slashIdx);

  const qIdx = s.indexOf("?");
  if (qIdx >= 0) s = s.slice(0, qIdx);

  const colonIdx = s.indexOf(":");
  if (colonIdx >= 0) s = s.slice(0, colonIdx);

  if (s.startsWith("www.")) s = s.slice(4);

  s = s.replace(/\.+$/, "");
  return s;
}

async function runUsqlWindow({ query, startTimestamp, endTimestamp, offsetUtc, pageSize }) {
  let pageOffset = 0;
  const allValues = [];

  while (true) {
    const resp = await rumUserSessionsClient.getUsqlResultAsTable({
      query,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
      pageOffset,
    });

    const values = resp?.values ?? [];
    allValues.push(...values);

    if (!pageSize || values.length < pageSize) break;
    pageOffset += pageSize;
  }

  return allValues;
}

export default async function () {
  const now = Date.now();

  // ======================
  // ✅ Tune these
  // ======================
  const windowDays = 3;
  const windowCount = 10;     // 30 days total
  const pageSize = 5000;
  const offsetUtc = -240;

  const windowMs = windowDays * 24 * 3600 * 1000;

  // ======================
  // 1) RAW: RUM app-domain (REAL_USER)
  // ======================
  const rumQuery =
    'SELECT application, domain, count(*) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'GROUP BY application, domain ' +
    'ORDER BY application, domain ' +
    'LIMIT 5000';

  // ======================
  // 2) RAW: Synthetic monitor-domain pairs (SYNTHETIC)
  // ======================
  const bmQuery =
    'SELECT usersession.browserMonitorName, domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY usersession.browserMonitorName, domain ' +
    'ORDER BY usersession.browserMonitorName, domain ' +
    'LIMIT 5000';

  // ======================
  // 3) RAW: Synthetic distinct URLs per domain (SYNTHETIC)
  // ======================
  const bmUrlsByDomainQuery =
    'SELECT domain, count(distinct targetUrl) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY domain ' +
    'ORDER BY domain ' +
    'LIMIT 5000';

  // ======================
  // Pull datasets via windowing
  // ======================
  const rumRows = [];
  const bmRows = [];

  // Domain-level URL aggregation across windows:
  // track max and sum, then apply: MAX unless SUM > 50 then SUM
  const urlAgg = new Map(); // domain -> { maxDistinctUrls, sumDistinctUrls }

  for (let i = 0; i < windowCount; i++) {
    const endTimestamp = now - i * windowMs;
    const startTimestamp = endTimestamp - windowMs;

    // ---- RUM window ----
    const rumValues = await runUsqlWindow({
      query: rumQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of rumValues) {
      const app = row[0];
      const domainRaw = row[1];
      const actions = Number(row[2]) || 0;

      const domain = normalizeHost(domainRaw);
      if (!app || !domain) continue;

      rumRows.push({ application: app, domain, actions });
    }

    // ---- BM window ----
    const bmValues = await runUsqlWindow({
      query: bmQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of bmValues) {
      const bmName = row[0];
      const domainRaw = row[1];

      const domain = normalizeHost(domainRaw);
      if (!bmName || !domain) continue;

      bmRows.push({ browserMonitorName: bmName, domain });
    }

    // ---- BM URLs-by-domain window ----
    const bmUrlValues = await runUsqlWindow({
      query: bmUrlsByDomainQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of bmUrlValues) {
      const domain = normalizeHost(row[0]);
      const urls = Number(row[1]) || 0;
      if (!domain) continue;

      const existing = urlAgg.get(domain);
      if (!existing) {
        urlAgg.set(domain, { maxDistinctUrls: urls, sumDistinctUrls: urls });
      } else {
        existing.sumDistinctUrls += urls;
        if (urls > existing.maxDistinctUrls) existing.maxDistinctUrls = urls;
      }
    }
  }

  // Apply rule: MAX unless SUM > 50 then SUM
  const urlMap = {}; // domain -> finalDistinctUrls
  for (const [domain, v] of urlAgg.entries()) {
    urlMap[domain] = v.sumDistinctUrls > 50 ? v.sumDistinctUrls : v.maxDistinctUrls;
  }

  // ======================
  // Merge/dedupe
  // - RUM: merge by (application||domain), SUM actions across windows
  // - BM: dedupe by (browserMonitorName||domain)
  // ======================
  const rumMerged = new Map();
  for (const r of rumRows) {
    const key = `${r.application}||${r.domain}`;
    const existing = rumMerged.get(key);
    if (existing) existing.actions += r.actions;
    else rumMerged.set(key, { application: r.application, domain: r.domain, actions: r.actions });
  }

  const bmUnique = new Map();
  for (const r of bmRows) {
    const key = `${r.browserMonitorName}||${r.domain}`;
    if (!bmUnique.has(key)) bmUnique.set(key, r);
  }

  // ======================
  // Build domain -> Set(BM) lookup
  // ======================
  const bmDomains = {}; // { [domain]: Set(bmName) }
  for (const { browserMonitorName, domain } of bmUnique.values()) {
    bmDomains[domain] = bmDomains[domain] || new Set();
    bmDomains[domain].add(browserMonitorName);
  }

  // ======================
  // Build per-application rollup:
  // application: { domains:Set, bm:Set, urls:number }
  // ======================
  const apps = {}; // { [app]: { domains:Set, bm:Set, urls:number } }

  for (const { application, domain } of rumMerged.values()) {
    apps[application] = apps[application] || { domains: new Set(), bm: new Set(), urls: 0 };
    apps[application].domains.add(domain);

    const bmSet = bmDomains[domain];
    if (bmSet) bmSet.forEach((m) => apps[application].bm.add(m));

    // Sum the finalized per-domain distinct URL counts for this application
    apps[application].urls += Number(urlMap[domain] || 0);
  }

  // ======================
  // Produce final table records
  // ======================
  const records = Object.entries(apps)
    .map(([application, v]) => ({
      application,
      num_domains: v.domains.size,
      domains: [...v.domains].sort().join(", "),
      num_BMs: v.bm.size,
      browser_monitors: [...v.bm].sort().join(", "),
      urls_w_BM: v.urls,
    }))
    .sort((a, b) => a.application.toLowerCase().localeCompare(b.application.toLowerCase()));

  // ======================
  // Return as dashboard table
  // ======================
  return {
    records,
    types: [
      {
        indexRange: [0, records.length],
        mappings: {
          application: { type: "string" },
          num_domains: { type: "float" },
          domains: { type: "string" },
          num_BMs: { type: "float" },
          browser_monitors: { type: "string" },
          urls_w_BM: { type: "float" },
        },
      },
    ],
  };
}

