import { rumUserSessionsClient } from "@dynatrace-sdk/client-classic-environment-v1";

/**
 * Normalize domain/host:
 * - trim/lowercase
 * - remove protocol, path, query, port
 * - remove leading www.
 * - remove trailing dots
 */
function normalizeHost(raw) {
  if (raw == null) return "";

  let s = String(raw).trim().toLowerCase();
  if (!s || s === "null" || s === "(null)" || s === "undefined") return "";

  s = s.replace(/^https?:\/\//, "");

  const slashIdx = s.indexOf("/");
  if (slashIdx >= 0) s = s.slice(0, slashIdx);

  const qIdx = s.indexOf("?");
  if (qIdx >= 0) s = s.slice(0, qIdx);

  const colonIdx = s.indexOf(":");
  if (colonIdx >= 0) s = s.slice(0, colonIdx);

  if (s.startsWith("www.")) s = s.slice(4);

  s = s.replace(/\.+$/, "");
  return s;
}

/**
 * Synthetic depth bucketing:
 * None / Very Light / Light / Moderate / Strong
 */
function getBmCoverageLevel(urls) {
  const n = Number(urls) || 0;
  if (n === 0) return "None";
  if (n >= 1 && n <= 3) return "Very Light";
  if (n >= 4 && n <= 6) return "Light";
  if (n >= 7 && n <= 14) return "Moderate";
  if (n >= 15 && n <= 100) return "Strong";
  return "100+ - Outlier (review)";
}

async function runUsqlWindow({ query, startTimestamp, endTimestamp, offsetUtc, pageSize }) {
  let pageOffset = 0;
  const allValues = [];

  while (true) {
    const resp = await rumUserSessionsClient.getUsqlResultAsTable({
      query,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
      pageOffset,
    });

    const values = resp?.values ?? [];
    allValues.push(...values);

    if (!pageSize || values.length < pageSize) break;
    pageOffset += pageSize;
  }

  return allValues;
}

export default async function () {
  const now = Date.now();

  // ======================
  // ✅ Tune these
  // ======================
  const topN = 32;
  const offsetUtc = -240;

  // Synthetic windowing
  const windowDays = 3;
  const windowCount = 10;   // 30 days total
  const pageSize = 5000;
  const windowMs = windowDays * 24 * 3600 * 1000;

  // Keep RUM lookback aligned with BM windowing
  const daysBack = windowDays * windowCount;
  const startTimestampRUM = now - daysBack * 24 * 3600 * 1000;
  const endTimestampRUM = now;

  // ======================
  // 1) RUM Top Domains (REAL_USER)
  // Increased LIMIT buffer to protect Top N after normalization
  // ======================
  const rumTopQueryLimit = Math.max(topN * 25, 2000);
  const rumTopQuery =
    `SELECT domain, count(*) ` +
    `FROM useraction ` +
    `WHERE usersession.userType = "REAL_USER" ` +
    `GROUP BY domain ` +
    `ORDER BY count(*) DESC ` +
    `LIMIT ${rumTopQueryLimit}`;

  const rumResp = await rumUserSessionsClient.getUsqlResultAsTable({
    query: rumTopQuery,
    startTimestamp: startTimestampRUM,
    endTimestamp: endTimestampRUM,
    offsetUtc,
  });

  const rumValues = rumResp?.values ?? [];

  const rumMerged = new Map(); // domain -> actions
  for (const row of rumValues) {
    const domain = normalizeHost(row[0]);
    const actions = Number(row[1]) || 0;
    if (!domain) continue;

    rumMerged.set(domain, (rumMerged.get(domain) || 0) + actions);
  }

  // ======================
  // 2) BM_Domains (SYNTHETIC): windowed + dedupe monitor||domain
  // ======================
  const bmDomainsQuery =
    'SELECT usersession.browserMonitorName, domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY usersession.browserMonitorName, domain ' +
    'ORDER BY usersession.browserMonitorName, domain ' +
    'LIMIT 5000';

  const bmUnique = new Map(); // key: bm||domain -> {browserMonitorName, domain}
  for (let i = 0; i < windowCount; i++) {
    const endTimestamp = now - i * windowMs;
    const startTimestamp = endTimestamp - windowMs;

    const values = await runUsqlWindow({
      query: bmDomainsQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of values) {
      const browserMonitorName = row[0];
      const domain = normalizeHost(row[1]);
      if (!browserMonitorName || !domain) continue;

      const key = `${browserMonitorName}||${domain}`;
      if (!bmUnique.has(key)) bmUnique.set(key, { browserMonitorName, domain });
    }
  }

  const bmMap = {}; // domain -> Set(monitorNames)
  for (const { browserMonitorName, domain } of bmUnique.values()) {
    bmMap[domain] = bmMap[domain] || new Set();
    bmMap[domain].add(browserMonitorName);
  }

  // ======================
  // 3) BM_URLs_byDomain (SYNTHETIC): windowed + MAX(urls)
  // ======================
  const bmUrlsByDomainQuery =
    'SELECT domain, count(distinct targetUrl) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY domain ' +
    'ORDER BY domain ' +
    'LIMIT 5000';

  const urlMap = {}; // domain -> urls
  for (let i = 0; i < windowCount; i++) {
    const endTimestamp = now - i * windowMs;
    const startTimestamp = endTimestamp - windowMs;

    const values = await runUsqlWindow({
      query: bmUrlsByDomainQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of values) {
      const domain = normalizeHost(row[0]);
      const urls = Number(row[1]) || 0;
      if (!domain) continue;

      urlMap[domain] = urlMap[domain] == null ? urls : Math.max(urlMap[domain], urls);
    }
  }

  // ======================
  // 4) Build rows
  // ======================
  const records = Array.from(rumMerged.entries())
    .map(([domain, actions]) => {
      const bmSet = bmMap[domain];

      const urls = urlMap[domain] ?? 0;
      const BM_coverage_level = getBmCoverageLevel(urls);

      return {
        domain,
        rum_actions: actions,
        num_BMs: bmSet ? bmSet.size : 0,
        browser_monitors: bmSet ? [...bmSet].sort().join(", ") : "",
        BM_coverage_level,
        urls_w_BM: urlMap[domain] ?? "",
        notes: "",
      };
    })
    .sort((a, b) => (Number(b.rum_actions) || 0) - (Number(a.rum_actions) || 0))
    .slice(0, topN);

  // ======================
  // 5) Return table
  // ======================
  return {
    records,
    types: [
      {
        indexRange: [0, records.length],
        mappings: {
          domain: { type: "string" },
          rum_actions: { type: "float" },
          num_BMs: { type: "float" },
          browser_monitors: { type: "string" },
          BM_coverage_level: { type: "string" },
          urls_w_BM: { type: "float" },
        },
      },
    ],
  };
}

