  const windowDays = 3;     // 3-day chunks
  const windowCount = 10;   // 30 days total
  const pageSize = 5000;
  const offsetUtc = -240;
  const windowMs = windowDays * 24 * 3600 * 1000;

  // ======================
  // RAW QUERIES
  // ======================

  // RUM_Domains_App (REAL_USER)
  const rumDomainsAppQuery =
    'SELECT application, domain, count(*) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'GROUP BY application, domain ' +
    'ORDER BY application, domain ' +
    'LIMIT 5000';

  // BM_Domains (SYNTHETIC monitor ↔ domain)
  const bmDomainsQuery =
    'SELECT usersession.browserMonitorName, domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY usersession.browserMonitorName, domain ' +
    'ORDER BY usersession.browserMonitorName, domain ' +
    'LIMIT 5000';

  // BM_URLs_byDomain (SYNTHETIC distinct URL depth per domain)
  const bmUrlsByDomainQuery =
    'SELECT domain, count(distinct targetUrl) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY domain ' +
    'ORDER BY domain ' +
    'LIMIT 5000';

  // ======================
  // 1) Pull windowed raw rows
  // ======================
  const rumRows = []; // { application, domain, actions }
  const bmRows = [];  // { browserMonitorName, domain }
  const urlRows = []; // { domain, urls }

  for (let i = 0; i < windowCount; i++) {
    const endTimestamp = now - i * windowMs;
    const startTimestamp = endTimestamp - windowMs;

    // --- RUM window
    const rumValues = await runUsqlWindow({
      query: rumDomainsAppQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of rumValues) {
      const application = row[0];
      const domain = normalizeHost(row[1]);
      const actions = Number(row[2]) || 0;

      if (!application || !domain || !isNonProdDomain(domain)) continue;
      rumRows.push({ application, domain, actions });
    }

    // --- BM Domains window
    const bmValues = await runUsqlWindow({
      query: bmDomainsQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of bmValues) {
      const browserMonitorName = row[0];
      const domain = normalizeHost(row[1]);

      if (!browserMonitorName || !domain || !isNonProdDomain(domain)) continue;
      bmRows.push({ browserMonitorName, domain });
