      query: bmUrlsByDomainQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of urlValues) {
      const domain = normalizeHost(row[0]);
      const urls = Number(row[1]) || 0;

      if (!domain || !isNonProdDomain(domain)) continue;
      urlRows.push({ domain, urls });
    }
