  // ======================
  const rumMerged = new Map(); // key: app||domain -> {application, domain, actions}
  for (const r of rumRows) {
    const key = `${r.application}||${r.domain}`;
    const existing = rumMerged.get(key);
    if (existing) existing.actions += r.actions;
    else rumMerged.set(key, { application: r.application, domain: r.domain, actions: r.actions });
  }

  const bmUnique = new Map(); // key: bm||domain -> {browserMonitorName, domain}
  for (const r of bmRows) {
    const key = `${r.browserMonitorName}||${r.domain}`;
    if (!bmUnique.has(key)) bmUnique.set(key, r);
  }

  const urlMaxByDomain = new Map(); // domain -> max(urls)
  for (const r of urlRows) {
    const existing = urlMaxByDomain.get(r.domain);
    if (existing == null) urlMaxByDomain.set(r.domain, r.urls);
    else urlMaxByDomain.set(r.domain, Math.max(existing, r.urls));
  }

  // ======================
  // 3) Build output rows
  // ======================
  const domains = {}; // domain -> { rum:Set(app), bm:Set(monitor), urls:number|string }

  for (const { application, domain } of rumMerged.values()) {
    domains[domain] = domains[domain] || { rum: new Set(), bm: new Set(), urls: "" };
    domains[domain].rum.add(application);
  }

  for (const { browserMonitorName, domain } of bmUnique.values()) {
    domains[domain] = domains[domain] || { rum: new Set(), bm: new Set(), urls: "" };
    domains[domain].bm.add(browserMonitorName);
  }

  // Only populate URL depth for domains that already exist in the view
  for (const d of Object.keys(domains)) {
