  const rumDomainUniverse = new Set(); // domains only, normalized
  const bmDomainUniverse = new Set();  // domains only, normalized

  const rumAppsByDomain = new Map();   // domain -> Set(app)
  const bmByDomain = new Map();        // domain -> Set(monitor)
  const urlMaxByDomain = new Map();    // domain -> max(distinct targetUrl)

