      const monitorName = (monitorNameRaw && String(monitorNameRaw).trim()) ? String(monitorNameRaw).trim() : "(unknown monitor)";
      if (!bmByDomain.has(domain)) bmByDomain.set(domain, new Set());
      bmByDomain.get(domain).add(monitorName);
