    const u1 = await runUsqlWindow({ query: bmUrlsByDomainQuery, startTimestamp, endTimestamp, offsetUtc, pageSize });
    for (const row of u1) {
      const domain = normalizeHost(row[0]);
      const urls = Number(row[1]) || 0;
      if (!domain) continue;

