        num_BMs: bmSet.size,
        browser_monitors: [...bmSet].sort().join(", "),
        BM_coverage_level: getBmCoverageLevel(urls),
        urls_w_BM: urls || "",
      };
    })
    .sort((a, b) => {
      const e = String(a.environment).localeCompare(String(b.environment), undefined, { sensitivity: "base" });
      if (e !== 0) return e;
      return String(a.domain).localeCompare(String(b.domain), undefined, { sensitivity: "base" });
    });

  return {
    records,
    types: [
      {
        indexRange: [0, records.length],
        mappings: {
          domain: { type: "string" },
          environment: { type: "string" },
          num_rum_apps: { type: "float" },
          rum_applications: { type: "string" },
          num_BMs: { type: "float" },
          browser_monitors: { type: "string" },
          BM_coverage_level: { type: "string" },
          urls_w_BM: { type: "float" },
        },
      },
    ],
  };
}

