  const windowDays = 3;
  const windowCount = 10;   // 30 days total
  const pageSize = 5000;
  const offsetUtc = -240;
  const windowMs = windowDays * 24 * 3600 * 1000;

  // ============================
  // Domain universe queries (FULL)
  // ============================
  // - RUM REAL_USER domains split by default app vs non-default
  // - BM SYNTHETIC domains from browser monitors
  const defaultAppName = "My Web Application";

  const rumDomains_NotDefaultApp =
    'SELECT distinct domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'AND useraction.application != "' + defaultAppName + '" ' +
    'LIMIT 5000';

  const rumDomains_DefaultAppOnly =
    'SELECT distinct domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'AND useraction.application = "' + defaultAppName + '" ' +
    'LIMIT 5000';

  const bmDomainsQuery =
    'SELECT usersession.browserMonitorName, domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY usersession.browserMonitorName, domain ' +
    'ORDER BY usersession.browserMonitorName, domain ' +
    'LIMIT 5000';

  // ============================
  // Session replay capture queries
  // ============================
  const totalSessionsQuery =
    'SELECT useraction.domain, count(distinct usersession.userSessionId) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'GROUP BY useraction.domain ' +
    'LIMIT 5000';

  const replaySessionsQuery =
    'SELECT useraction.domain, count(distinct usersession.userSessionId) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" and usersession.hasSessionReplay=true ' +
    'GROUP BY useraction.domain ' +
    'LIMIT 5000';

  // ============================
  // Sets + aggregation maps
  // ============================
  const rumDomains = new Set();
  const bmDomains = new Set();

  const totalSessionsByDomain = new Map();
  const replaySessionsByDomain = new Map();

  for (let i = 0; i < windowCount; i++) {
    const end = now - i * windowMs;
    const start = end - windowMs;

    // ---- RUM domain universe (REAL_USER) split default vs non-default
    (await runUsqlWindow({ query: rumDomains_NotDefaultApp, startTimestamp: start, endTimestamp: end, offsetUtc, pageSize }))
      .forEach(r => {
        const d = normalizeHost(r[0]); // SELECT distinct domain -> index 0
        if (d) rumDomains.add(d);
      });

    (await runUsqlWindow({ query: rumDomains_DefaultAppOnly, startTimestamp: start, endTimestamp: end, offsetUtc, pageSize }))
      .forEach(r => {
        const d = normalizeHost(r[0]); // SELECT distinct domain -> index 0
        if (d) rumDomains.add(d);
      });

    // ---- BM domain universe (SYNTHETIC)
    (await runUsqlWindow({ query: bmDomainsQuery, startTimestamp: start, endTimestamp: end, offsetUtc, pageSize }))
      .forEach(r => {
        const d = normalizeHost(r[1]); // [0]=browserMonitorName, [1]=domain
        if (d) bmDomains.add(d);
      });

    // ---- Total sessions by domain (REAL_USER)
    (await runUsqlWindow({ query: totalSessionsQuery, startTimestamp: start, endTimestamp: end, offsetUtc, pageSize }))
      .forEach(r => {
        const d = normalizeHost(r[0]); // [0]=domain, [1]=count
        if (d) addToSumMap(totalSessionsByDomain, d, r[1]);
      });

    // ---- Replay sessions by domain (REAL_USER + hasSessionReplay)
    (await runUsqlWindow({ query: replaySessionsQuery, startTimestamp: start, endTimestamp: end, offsetUtc, pageSize }))
      .forEach(r => {
        const d = normalizeHost(r[0]); // [0]=domain, [1]=count
        if (d) addToSumMap(replaySessionsByDomain, d, r[1]);
      });
  }

  // ============================
  // Full domain universe = RUM + BM
  // ============================
  const domainSet = new Set([...rumDomains, ...bmDomains]);

  const records = Array.from(domainSet)
    .map(domain => {
      const total = totalSessionsByDomain.get(domain) || 0;
      const replay = replaySessionsByDomain.get(domain) || 0;
      const replay_rate_perc = total > 0 ? (replay / total) * 100 : 0;

      return {
        domain,
        replay_rate_perc: Math.round(replay_rate_perc),
      };
    })
    // Descending by replay_rate_perc
    .sort((a, b) => b.replay_rate_perc - a.replay_rate_perc);

  return {
    records,
    types: [
      {
        indexRange: [0, records.length],
        mappings: {
          domain: { type: "string" },
          replay_rate_perc: { type: "double" },
        },
      },
    ],
  };
}

