import { rumUserSessionsClient } from "@dynatrace-sdk/client-classic-environment-v1";

/**
 * Normalize domain/host:
 * - trim/lowercase
 * - treat null-like strings as empty
 * - remove protocol, path, query, port
 * - remove leading www.
 * - remove trailing dots
 */
function normalizeHost(raw) {
  if (raw == null) return "";

  let s = String(raw).trim().toLowerCase();
  if (!s || s === "null" || s === "(null)" || s === "undefined") return "";

  s = s.replace(/^https?:\/\//, "");

  const slashIdx = s.indexOf("/");
  if (slashIdx >= 0) s = s.slice(0, slashIdx);

  const qIdx = s.indexOf("?");
  if (qIdx >= 0) s = s.slice(0, qIdx);

  const colonIdx = s.indexOf(":");
  if (colonIdx >= 0) s = s.slice(0, colonIdx);

  if (s.startsWith("www.")) s = s.slice(4);

  s = s.replace(/\.+$/, "");
  return s;
}

/**
 * Helper: run a USQL query over a time window with paging.
 */
async function runUsqlWindow({ query, startTimestamp, endTimestamp, offsetUtc, pageSize }) {
  let pageOffset = 0;
  const allValues = [];

  while (true) {
    const resp = await rumUserSessionsClient.getUsqlResultAsTable({
      query,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
      pageOffset,
    });

    const values = resp?.values ?? [];
    allValues.push(...values);

    if (!pageSize || values.length < pageSize) break;
    pageOffset += pageSize;
  }

  return allValues;
}

/**
 * Helper: sum into a Map(domain -> number)
 */
function addToSumMap(map, key, value) {
  const prev = map.get(key) || 0;
  map.set(key, prev + (Number(value) || 0));
}

export default async function () {
  const now = Date.now();

  // ======================
  // Sampling/windowing
  // ======================
  const windowDays = 3;     // 3-day chunks
  const windowCount = 10;   // 30 days total
  const pageSize = 5000;
  const offsetUtc = -240;   // adjust if needed
  const windowMs = windowDays * 24 * 3600 * 1000;

  // ======================
  // QUERIES
  // ======================

  // 1) RUM app->domain inventory (for num_rum_apps)
  const rumDomainsAppQuery =
    'SELECT application, domain, count(*) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'GROUP BY application, domain ' +
    'ORDER BY application, domain ' +
    'LIMIT 5000';

  // 2) BM domains (optional but useful to keep "full domain universe")
  const bmDomainsQuery =
    'SELECT usersession.browserMonitorName, domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY usersession.browserMonitorName, domain ' +
    'ORDER BY usersession.browserMonitorName, domain ' +
    'LIMIT 5000';

  // 3) Sessions by domain (REAL_USER)
  // Per your request:
  const totalSessionsQuery =
    'SELECT useraction.domain, count(distinct userSessionId) as sessions ' +
    'FROM usersession ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'GROUP BY useraction.domain ' +
    'LIMIT 5000';

  // 4) Sessions with replay by domain (REAL_USER + hasSessionReplay=true)
  // Per your request:
  const replaySessionsQuery =
    'SELECT useraction.domain, count(distinct userSessionId) as sessions ' +
    'FROM usersession ' +
    'WHERE usersession.userType = "REAL_USER" and hasSessionReplay=true ' +
    'GROUP BY useraction.domain ' +
    'LIMIT 5000';

  // ======================
  // 1) Pull windowed raw rows
  // ======================
  const rumRows = []; // { application, domain }
  const bmRows = [];  // { browserMonitorName, domain }

  const totalSessionsByDomain = new Map(); // domain -> summed sessions across windows
  const replaySessionsByDomain = new Map(); // domain -> summed replay sessions across windows

  for (let i = 0; i < windowCount; i++) {
    const endTimestamp = now - i * windowMs;
    const startTimestamp = endTimestamp - windowMs;

    // --- RUM app/domain window
    const rumValues = await runUsqlWindow({
      query: rumDomainsAppQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of rumValues) {
      const application = row[0];
      const domain = normalizeHost(row[1]);
      if (!application || !domain) continue;
      rumRows.push({ application, domain });
    }

    // --- BM domains window (to keep the "full list of domains from both RUM and BM" behavior)
    const bmValues = await runUsqlWindow({
      query: bmDomainsQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of bmValues) {
      const browserMonitorName = row[0];
      const domain = normalizeHost(row[1]);
      if (!browserMonitorName || !domain) continue;
      bmRows.push({ browserMonitorName, domain });
    }

    // --- Total sessions window
    const totalValues = await runUsqlWindow({
      query: totalSessionsQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of totalValues) {
      const domain = normalizeHost(row[0]);
      const sessions = Number(row[1]) || 0;
      if (!domain) continue;
      addToSumMap(totalSessionsByDomain, domain, sessions);
    }

    // --- Replay sessions window
    const replayValues = await runUsqlWindow({
      query: replaySessionsQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });

    for (const row of replayValues) {
      const domain = normalizeHost(row[0]);
      const sessions = Number(row[1]) || 0;
      if (!domain) continue;
      addToSumMap(replaySessionsByDomain, domain, sessions);
    }
  }

  // ======================
  // 2) Dedupe RUM app||domain and BM monitor||domain (inventory only)
  // ======================
  const rumUniqueAppDomain = new Map(); // key: app||domain -> {application, domain}
  for (const r of rumRows) {
    const key = `${r.application}||${r.domain}`;
    if (!rumUniqueAppDomain.has(key)) rumUniqueAppDomain.set(key, r);
  }

  const bmUnique = new Map(); // key: bm||domain -> {browserMonitorName, domain}
  for (const r of bmRows) {
    const key = `${r.browserMonitorName}||${r.domain}`;
    if (!bmUnique.has(key)) bmUnique.set(key, r);
  }

  // ======================
  // 3) Build unified domain universe
  //    Union of:
  //    - RUM inventory
  //    - BM inventory
  //    - Any domain that appears in session queries
  // ======================
  const domainSet = new Set();

  for (const { domain } of rumUniqueAppDomain.values()) domainSet.add(domain);
  for (const { domain } of bmUnique.values()) domainSet.add(domain);
  for (const domain of totalSessionsByDomain.keys()) domainSet.add(domain);
  for (const domain of replaySessionsByDomain.keys()) domainSet.add(domain);

  // Build per-domain set of RUM applications
  const rumAppsByDomain = {}; // domain -> Set(app)
  for (const { application, domain } of rumUniqueAppDomain.values()) {
    rumAppsByDomain[domain] = rumAppsByDomain[domain] || new Set();
    rumAppsByDomain[domain].add(application);
  }

  // ======================
  // 4) Build output records
  // ======================
  const records = Array.from(domainSet).map((domain) => {
    const total_sessions = Number(totalSessionsByDomain.get(domain)) || 0;
    const sessions_w_replay = Number(replaySessionsByDomain.get(domain)) || 0;

    // Avoid divide-by-zero; keep as null so table can sort/filter cleanly
    const replay_rate_pct =
      total_sessions > 0 ? (sessions_w_replay / total_sessions) * 100 : null;

    const rumSet = rumAppsByDomain[domain] || new Set();
    const num_rum_apps = rumSet.size;

    return {
      domain,
      total_sessions,
      sessions_w_replay,
      "replay_rate_%": Math.round(replay_rate_pct),
      num_rum_apps,
    };
  });

  // Suggested default sort: highest replay rate, then highest sessions, then domain alpha
  records.sort((a, b) => {
    const ar = a["replay_rate_%"];
    const br = b["replay_rate_%"];
    const arN = ar == null ? -1 : ar;
    const brN = br == null ? -1 : br;
    if (brN !== arN) return brN - arN;

    if (b.total_sessions !== a.total_sessions) return b.total_sessions - a.total_sessions;
    return String(a.domain).localeCompare(String(b.domain), undefined, { sensitivity: "base" });
  });

  // ======================
  // 5) Return table
  // ======================
  return {
    records,
    types: [
      {
        indexRange: [0, records.length],
        mappings: {
          domain: { type: "string" },
          total_sessions: { type: "float" },
          sessions_w_replay: { type: "float" },
          "replay_rate_%": { type: "float" },
          num_rum_apps: { type: "float" },
        },
      },
    ],
  };
}

