import { rumUserSessionsClient } from "@dynatrace-sdk/client-classic-environment-v1";

/**
 * Normalize domain/host consistent:
 * - trim/lowercase
 * - treat null-like strings as empty
 * - remove protocol, path, query, port
 * - remove leading www.
 * - remove trailing dots
 */
function normalizeHost(raw) {
  if (raw == null) return "";

  let s = String(raw).trim().toLowerCase();
  if (!s || s === "null" || s === "(null)" || s === "undefined") return "";

  s = s.replace(/^https?:\/\//, "");

  const slashIdx = s.indexOf("/");
  if (slashIdx >= 0) s = s.slice(0, slashIdx);

  const qIdx = s.indexOf("?");
  if (qIdx >= 0) s = s.slice(0, qIdx);

  const colonIdx = s.indexOf(":");
  if (colonIdx >= 0) s = s.slice(0, colonIdx);

  if (s.startsWith("www.")) s = s.slice(4);

  s = s.replace(/\.+$/, "");
  return s;
}

async function runUsqlWindow({ query, startTimestamp, endTimestamp, offsetUtc, pageSize }) {
  let pageOffset = 0;
  const allValues = [];

  while (true) {
    const resp = await rumUserSessionsClient.getUsqlResultAsTable({
      query,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
      pageOffset,
    });

    const values = resp?.values ?? [];
    allValues.push(...values);

    // stop when fewer than a full page is returned
    if (!pageSize || values.length < pageSize) break;
    pageOffset += pageSize;
  }

  return allValues;
}

export default async function () {
  const now = Date.now();

  // ======================
  // Rolling window config
  // ======================
  const windowDays = 3;
  const windowCount = 10;
  const pageSize = 5000;
  const offsetUtc = -240;
  const windowMs = windowDays * 24 * 3600 * 1000;

  // ======================
  // Sets for dedupe (normalized)
  // ======================
  const allDomains = new Set(); // union: RUM REAL_USER + BM SYNTHETIC
  const srDomains = new Set();  // SR traffic: REAL_USER + hasSessionReplay=true

  // ======================
  // USQL queries (split default app vs not)
  // ======================
  const defaultAppName = "My Web Application";

  // --- RUM: domains observed in REAL_USER traffic (denominator contributor)
  const rumDomains_NotDefaultApp =
    'SELECT distinct domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'AND useraction.application != "' + defaultAppName + '" ' +
    'LIMIT 5000';

  const rumDomains_DefaultAppOnly =
    'SELECT distinct domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'AND useraction.application = "' + defaultAppName + '" ' +
    'LIMIT 5000';

  // --- SR: domains that have Session Replay traffic (numerator)
  const srDomains_NotDefaultApp =
    'SELECT distinct domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'AND usersession.hasSessionReplay = true ' +
    'AND useraction.application != "' + defaultAppName + '" ' +
    'LIMIT 5000';

  const srDomains_DefaultAppOnly =
    'SELECT distinct domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'AND usersession.hasSessionReplay = true ' +
    'AND useraction.application = "' + defaultAppName + '" ' +
    'LIMIT 5000';

  // --- BM: domains observed in SYNTHETIC traffic (denominator contributor)
  const bmDomainsQuery =
    'SELECT usersession.browserMonitorName, domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY usersession.browserMonitorName, domain ' +
    'ORDER BY usersession.browserMonitorName, domain ' +
    'LIMIT 5000';

  // ======================
  // Windowed execution
  // ======================
  for (let i = 0; i < windowCount; i++) {
    const endTimestamp = now - i * windowMs;
    const startTimestamp = endTimestamp - windowMs;

    // ---- RUM domains (REAL_USER) -> allDomains
    const rumVals1 = await runUsqlWindow({
      query: rumDomains_NotDefaultApp,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });
    for (const row of rumVals1) {
      const domain = normalizeHost(row[0]);
      if (domain) allDomains.add(domain);
    }

    const rumVals2 = await runUsqlWindow({
      query: rumDomains_DefaultAppOnly,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });
    for (const row of rumVals2) {
      const domain = normalizeHost(row[0]);
      if (domain) allDomains.add(domain);
    }

    // ---- SR domains (REAL_USER + hasSessionReplay) -> srDomains
    const srVals1 = await runUsqlWindow({
      query: srDomains_NotDefaultApp,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });
    for (const row of srVals1) {
      const domain = normalizeHost(row[0]);
      if (domain) srDomains.add(domain);
    }

    const srVals2 = await runUsqlWindow({
      query: srDomains_DefaultAppOnly,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });
    for (const row of srVals2) {
      const domain = normalizeHost(row[0]);
      if (domain) srDomains.add(domain);
    }

    // ---- BM domains (SYNTHETIC) -> allDomains
    const bmVals = await runUsqlWindow({
      query: bmDomainsQuery,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
    });
    for (const row of bmVals) {
      // row[0] = browserMonitorName, row[1] = domain
      const domain = normalizeHost(row[1]);
      if (domain) allDomains.add(domain);
    }

  }

  // ======================
  // Gauge value (%)
  // ======================
  if (allDomains.size === 0) return 0;

  const percent = (srDomains.size / allDomains.size) * 100;
  return Math.round(percent);
}

