import { rumUserSessionsClient } from "@dynatrace-sdk/client-classic-environment-v1";

function normalizeHost(raw) {
  if (raw == null) return "";

  let s = String(raw).trim().toLowerCase();
  if (!s || s === "null" || s === "(null)" || s === "undefined") return "";

  s = s.replace(/^https?:\/\//, "");

  const slashIdx = s.indexOf("/");
  if (slashIdx >= 0) s = s.slice(0, slashIdx);

  const qIdx = s.indexOf("?");
  if (qIdx >= 0) s = s.slice(0, qIdx);

  const colonIdx = s.indexOf(":");
  if (colonIdx >= 0) s = s.slice(0, colonIdx);

  if (s.startsWith("www.")) s = s.slice(4);

  s = s.replace(/\.+$/, "");
  return s;
}

function getCoverageBand(urls) {
  const n = Number(urls) || 0;
  if (n === 0) return "0 - None";
  if (n <= 3) return "1–3 - Very Light";
  if (n <= 6) return "4–6 - Light";
  if (n <= 14) return "7–14 - Moderate";
  if (n <= 100) return "15–100 - Strong";
  return "100+ - Outlier (review)";
}

// Ensures the sort order exactly matches your band logic above
function coverageRank(band) {
  switch (band) {
    case "0 - None":
      return 0;
    case "1–3 - Very Light":
      return 1;
    case "4–6 - Light":
      return 2;
    case "7–14 - Moderate":
      return 3;
    case "15–100 - Strong":
      return 4;
    case "100+ - Outlier (review)":
      return 5;
    default:
      return 99; // safety for unexpected strings
  }
}

async function runUsqlWindow({ query, startTimestamp, endTimestamp, offsetUtc, pageSize }) {
  let pageOffset = 0;
  const allValues = [];

  while (true) {
    const resp = await rumUserSessionsClient.getUsqlResultAsTable({
      query,
      startTimestamp,
      endTimestamp,
      offsetUtc,
      pageSize,
      pageOffset,
    });

    const values = resp?.values ?? [];
    allValues.push(...values);

    if (!pageSize || values.length < pageSize) break;
    pageOffset += pageSize;
  }

  return allValues;
}

export default async function () {
  const now = Date.now();

  // Rolling windows
  const windowDays = 3;
  const windowCount = 10;
  const pageSize = 5000;
  const offsetUtc = -240;
  const windowMs = windowDays * 24 * 3600 * 1000;

  // ======================
  // FULL universe queries
  // ======================
  const defaultAppName = "My Web Application";

  // RUM domain universe (REAL_USER), split default vs non-default app
  const rumDomains_NotDefaultApp =
    'SELECT distinct domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'AND useraction.application != "' + defaultAppName + '" ' +
    'LIMIT 5000';

  const rumDomains_DefaultAppOnly =
    'SELECT distinct domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "REAL_USER" ' +
    'AND useraction.application = "' + defaultAppName + '" ' +
    'LIMIT 5000';

  // BM domain universe (SYNTHETIC)
  const bmDomainsQuery =
    'SELECT usersession.browserMonitorName, domain ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY usersession.browserMonitorName, domain ' +
    'ORDER BY usersession.browserMonitorName, domain ' +
    'LIMIT 5000';

  // BM URL coverage per domain (used for urls_w_bm metric)
  const bmUrlsByDomainQuery =
    'SELECT domain, count(distinct targetUrl) ' +
    'FROM useraction ' +
    'WHERE usersession.userType = "SYNTHETIC" ' +
    'GROUP BY domain ' +
    'LIMIT 5000';

  const rumDomains = new Set();     // normalized
  const bmDomains = new Set();      // normalized
  const urlMaxByDomain = new Map(); // normalized domain -> max distinct targetUrl seen in any window

  for (let i = 0; i < windowCount; i++) {
    const end = now - i * windowMs;
    const start = end - windowMs;

    // --- RUM (non-default app)
    const rumVals1 = await runUsqlWindow({
      query: rumDomains_NotDefaultApp,
      startTimestamp: start,
      endTimestamp: end,
      offsetUtc,
      pageSize,
    });
    rumVals1.forEach(r => {
      const d = normalizeHost(r[0]); // distinct domain -> index 0
      if (d) rumDomains.add(d);
    });

    // --- RUM (default app only)
    const rumVals2 = await runUsqlWindow({
      query: rumDomains_DefaultAppOnly,
      startTimestamp: start,
      endTimestamp: end,
      offsetUtc,
      pageSize,
    });
    rumVals2.forEach(r => {
      const d = normalizeHost(r[0]); // distinct domain -> index 0
      if (d) rumDomains.add(d);
    });

    // --- BM domain universe
    const bmVals = await runUsqlWindow({
      query: bmDomainsQuery,
      startTimestamp: start,
      endTimestamp: end,
      offsetUtc,
      pageSize,
    });
    bmVals.forEach(r => {
      const d = normalizeHost(r[1]); // [0]=browserMonitorName, [1]=domain
      if (d) bmDomains.add(d);
    });

    // --- BM URL counts by domain (keep max across windows)
    const urlVals = await runUsqlWindow({
      query: bmUrlsByDomainQuery,
      startTimestamp: start,
      endTimestamp: end,
      offsetUtc,
      pageSize,
    });
    urlVals.forEach(r => {
      const d = normalizeHost(r[0]);     // [0]=domain
      const urls = Number(r[1]) || 0;    // [1]=count(distinct targetUrl)
      if (!d) return;

      const existing = urlMaxByDomain.get(d);
      urlMaxByDomain.set(d, existing == null ? urls : Math.max(existing, urls));
    });
  }

  // ======================
  // FULL domain universe (standardized):
  // only RUM + BM domains (normalized)
  // ======================
  const domainSet = new Set([...rumDomains, ...bmDomains]);

  const records = Array.from(domainSet)
    .map(domain => {
      const urls = urlMaxByDomain.get(domain) ?? 0; // domains with no BM get 0
      const band = getCoverageBand(urls);
      return {
        domain,
        urls_w_bm: urls,
        coverage_band: band,
        _coverage_rank: coverageRank(band), // helper for sorting only
      };
    })
    .sort((a, b) => {
      // 1) coverage band order (0-None first)
      if (a._coverage_rank !== b._coverage_rank) return a._coverage_rank - b._coverage_rank;
      // 2) domain name ascending
      return a.domain.localeCompare(b.domain);
    })
    .map(({ _coverage_rank, ...rest }) => rest); // remove helper key before returning

  return {
    records,
    types: [
      {
        indexRange: [0, records.length],
        mappings: {
          domain: { type: "string" },
          urls_w_bm: { type: "float" },
          coverage_band: { type: "string" },
        },
      },
    ],
  };
}
